package nl.slimov.app;
import android.content.Context;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.GZIPInputStream;import org.json.*;
public final class MonitorNetwork {
 private static final Map<String,String> tags=new HashMap<>();private static final Map<String,byte[]> cache=new HashMap<>();private static final Map<String,Long> times=new HashMap<>();
 public static synchronized byte[] get(String url,int limit,long ttl,String nsKey)throws Exception{long now=System.currentTimeMillis();if(cache.containsKey(url)&&now-times.getOrDefault(url,0L)<ttl)return cache.get(url);HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","SlimOV/0.4.1 (https://github.com/lewis091dc/slimOV)");c.setRequestProperty("Accept-Encoding","gzip");if(nsKey!=null&&!nsKey.isEmpty())c.setRequestProperty("Ocp-Apim-Subscription-Key",nsKey);if(tags.containsKey(url))c.setRequestProperty("If-None-Match",tags.get(url));try{int status=c.getResponseCode();if(status==304&&cache.containsKey(url)){times.put(url,now);return cache.get(url);}if(status!=200)throw new IOException(status==401||status==403?"NS HTTP "+status+": sleutel niet geaccepteerd of abonnement heeft geen toegang tot Virtual Train API":status==429?"Bronlimiet bereikt; probeer later opnieuw":"Bron niet bereikbaar (HTTP "+status+")");InputStream input=c.getInputStream();if("gzip".equalsIgnoreCase(c.getContentEncoding()))input=new GZIPInputStream(input);byte[] body=LiveStream.readBounded(input,limit);if(cache.size()>20){cache.clear();times.clear();tags.clear();}cache.put(url,body);times.put(url,now);String tag=c.getHeaderField("ETag");if(tag!=null)tags.put(url,tag);return body;}finally{c.disconnect();}}
 public static JSONObject trip(String id)throws Exception{return new JSONObject(new String(get("https://api.transitous.org/api/v6/trip?tripId="+URLEncoder.encode(id,"UTF-8")+"&detailedLegs=false&joinInterlinedLegs=false&withScheduledSkippedStops=true&language=nl",4*1024*1024,45000,null),StandardCharsets.UTF_8));}
 public static JSONObject vehicles()throws Exception{return Proto.vehicles(get("https://gtfs.ovapi.nl/nl/vehiclePositions.pb",10*1024*1024,15000,null));}
 public static JSONObject alerts()throws Exception{return Proto.alerts(get("https://gtfs.ovapi.nl/nl/alerts.pb",20*1024*1024,60000,null));}
 public static synchronized void invalidateNs(){for(String url:new ArrayList<>(cache.keySet()))if(url.startsWith("https://gateway.apiportal.ns.nl/")){cache.remove(url);times.remove(url);tags.remove(url);}}
 public static Object ns(Context c,String path)throws Exception{return nsResource(c,"virtual-train-api",path);}
 private static Object nsResource(Context c,String service,String path)throws Exception{String key=SecretStore.get(c);if(key.isEmpty())throw new Exception("Stel eerst je NS API-sleutel in bij Instellingen");String text=new String(get("https://gateway.apiportal.ns.nl/"+service+path,8*1024*1024,30000,key),StandardCharsets.UTF_8);return text.trim().startsWith("[")?new JSONArray(text):new JSONObject(text);}
 public static JSONObject nsJourney(Context c,String number,String when,boolean geometry)throws Exception{InstantCheck(when);JSONObject result=NsJourney.make(nsResource(c,"reisinformatie-api","/api/v2/journey?train="+URLEncoder.encode(number,"UTF-8")+"&dateTime="+URLEncoder.encode(when,"UTF-8")+"&omitCrowdForecast=true"),number,when);if(geometry){JSONArray codes=result.optJSONArray("_stationCodes");if(codes!=null&&codes.length()>=2){List<String> list=new ArrayList<>();for(int i=0;i<codes.length();i++)list.add(codes.getString(i));try{result.put("_geoJson",nsResource(c,"Spoorkaart-API","/api/v1/traject.geojson?stations="+URLEncoder.encode(String.join(",",list),"UTF-8")));}catch(Exception e){result.put("_geometryStatus","Exacte spoorroute niet ontvangen");}}}return result;}
 private static void InstantCheck(String when)throws Exception{try{java.time.Instant.parse(when);}catch(Exception e){throw new Exception("Ongeldig NS-rittijdstip");}}
 public static JSONObject trip(Context c,String id,boolean geometry)throws Exception{if(!id.startsWith("nsjourney:"))return trip(id);java.util.regex.Matcher match=java.util.regex.Pattern.compile("^nsjourney:([0-9]{1,6}):(.+)$").matcher(id);if(!match.matches())throw new Exception("Ongeldige NS-ritkoppeling");return nsJourney(c,match.group(1),match.group(2),geometry);}
}
